<script setup lang="ts">
/**
 * Modal side sheet (`design/components/drawer.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/drawer.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, watch } from 'vue'

import * as zag from '@zag-js/dialog'
import { normalizeProps, useMachine } from '@zag-js/vue'

import {
  agentMember,
  focusPlace,
  focusReturnTarget,
  modalFocusTarget,
  useDirection,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/overlays/drawer.module.css'
import Button from '../controls/Button.vue'

export type DrawerSide = NonNullable<DrawerProps['side']>

export interface DrawerProps {
  /**
   * The ✕'s accessible name, as in Dialog; localized hosts replace the default `Close`.
   */
  closeLabel?: string
  defaultOpen?: boolean
  description?: string
  /**
   * `false` removes ✕ and ignores Escape and outside clicks, forcing a choice.
   */
  dismissible?: boolean
  /**
   * The same as Dialog's, from the shared focus code: unset focuses the first tabbable per the
   * focus-order rule, and `dismiss` suits a panel asking whether you meant it.
   */
  initialFocus?: 'primary' | 'dismiss'
  open?: boolean
  side?: 'start' | 'end' | 'bottom'
  /**
   * Inline size for a start/end sheet, block size for a bottom one. Both derive from the space
   * scale, so a roomier theme gets a larger sheet.
   */
  size?: 'sm' | 'md' | 'lg'
  title: string
}

defineOptions({ name: 'Drawer', inheritAttrs: false })

const props = withDefaults(defineProps<DrawerProps>(), {
  closeLabel: 'Close',
  defaultOpen: undefined,
  dismissible: true,
  initialFocus: 'primary',
  open: undefined,
  side: 'end',
  size: 'md',
})
const emit = defineEmits<{ openChange: [open: boolean] }>()
defineSlots<{
  default?: (props: Record<string, never>) => unknown
  footer?: (props: Record<string, never>) => unknown
}>()
const uid = useId()
const returnTo = ref(null as ReturnType<typeof focusPlace>)
const panel = useTemplateRef<HTMLElement>('panel')
const scrim = useTemplateRef<HTMLElement>('scrim')
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    open: props.open,
    defaultOpen: props.defaultOpen,
    closeOnEscape: props.dismissible,
    closeOnInteractOutside: props.dismissible,
    initialFocusEl: () => modalFocusTarget(panel.value, props.initialFocus),
    finalFocusEl: () => focusReturnTarget(returnTo.value, [panel.value]),
    onOpenChange: (details) => {
      emit('openChange', details.open)
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const scrimPresent = usePresence(() => api.value.open, scrim, 'dialog.scrim')
const panelPresent = usePresence(() => api.value.open, panel, 'drawer.panel', {
  get sheetSide() {
    return props.side
  },
})
const effect1 = () => {
  api.value.open && (returnTo.value = focusPlace(document.activeElement))
}
onMounted(effect1)
watch(() => api.value.open, effect1, { flush: 'post' })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'Drawer',
    element: () => panel.value,
    state: () => ({ open: api.value.open }),
    actions: {
      close: () =>
        (() => {
          if (!props.dismissible)
            throw new Error('The drawer asks for a choice among its own actions.')
          if (api.value.open) api.value.setOpen(false)
        })(),
    },
  })
  release2 = () => {
    ran()
  }
}
onMounted(effect2)
onBeforeUnmount(() => release2?.())
</script>

<template>
  <Teleport to="body">
    <!-- scrim -->
    <div
      v-if="scrimPresent"
      ref="scrim"
      v-bind="api.getBackdropProps()"
      :class="styles.scrim"
      :hidden="undefined"
    />
    <!-- positioner -->
    <div
      v-if="panelPresent"
      v-bind="api.getPositionerProps()"
      :class="styles.positioner"
      :data-side="side"
    >
      <!-- panel -->
      <div
        ref="panel"
        v-bind="api.getContentProps()"
        :class="styles.panel"
        :hidden="undefined"
        :data-side="side"
        :data-size="size"
        data-member="drawer"
      >
        <!-- header -->
        <div :class="styles.header">
          <!-- heading -->
          <div :class="styles.heading">
            <!-- title -->
            <h2 v-bind="api.getTitleProps()" :class="styles.title">
              {{ title }}
            </h2>
            <!-- description -->
            <p
              v-if="description !== undefined"
              v-bind="api.getDescriptionProps()"
              :class="styles.description"
            >
              {{ description }}
            </p>
          </div>
          <!-- close -->
          <div v-if="dismissible" :class="styles.close" data-dialog-part="close">
            <Button
              variant="ghost"
              tone="neutral"
              size="sm"
              :iconOnly="true"
              icon="close"
              :label="closeLabel"
              @click="api.setOpen(false)"
            />
          </div>
        </div>
        <!-- body -->
        <div :class="styles.body" data-dialog-part="body">
          <slot />
        </div>
        <!-- footer -->
        <div v-if="$slots.footer" :class="styles.footer" data-dialog-part="footer">
          <slot name="footer" />
        </div>
      </div>
    </div>
  </Teleport>
</template>
